function RaceJCPView:TestEnter()
    local isCanMatch=true
    local Datas={}
    Datas.starts={}
    for i = 1, 3 do
        local carIndex = RaceJcpManager:Get():GetCarIndexByJcpIndex(i)
        if CarDataManager:Get():CheckCarCompleteness(carIndex) then
            Datas.starts[i]={trackId=RaceJcpManager:Get():GetTrackData().id,scenceId=RaceJcpManager:Get():GetSceneID(),carId=carIndex}
        else
            isCanMatch=false
            break
        end
    end
    if isCanMatch then
        RaceJcpManager:Get():SetRaceType(RaceJcpRaceType.Test)
        RaceJcpManager:Get():BeginBattle(Datas,false)
    end
end

