function RaceJCPView:UpdateCarSign()
    if RaceJcpManager:Get():GetCurState()<RaceJCPType.RaceOver then
        local active=false
        for i = 1, 3 do
            if  RaceJcpManager:Get():GetCarIndexByJcpIndex(i) == self.curCarIndex then
                active=true
                break
            end
        end
        self.curCarApplyJCP=active
        CommonHelper:CSGameObjectSetActive(self.CarApplyJCPSign,active)
    else
        CommonHelper:CSGameObjectSetActive(self.CarApplyJCPSign,false)
    end
end

