function RaceJCPView:BuildApplyCars()
    local buildParams=RaceJcpManager:Get():GetBuildParams()
    if buildParams and #buildParams>0 then
        CarBuilderTextureManager:Get():BuildMore(buildParams,function(carList)
        end,function(textureBuilder)
            for i = 1, #(RaceJcpManager:Get().JcpData.jcpIndexMap) do
                if textureBuilder.BuilderData.idx == RaceJcpManager:Get().JcpData.jcpIndexMap[i] then
                    CommonHelper:GetComponentSetUITextureByTexture("icon", self.items[i], textureBuilder.Texture)
                end
            end
            if textureBuilder.BuilderData.idx == self.curCarIndex  then
                local root = HomeSceneHelper:GetCarRoot_JCP()
                if root then
                    UIUtil.SetParentGameObject(root, textureBuilder.CarObj)
                    HomeSceneCarMeshHelper:Get():SetMeshCtrl(true,root,SceneChangeID.RefitTable)
                end
            else
                CommonHelper:CSGameObjectSetActive(textureBuilder.CarObj,false)
            end
        end)
    end
end

