function RaceJCPView:SetGroupTranscript()
    local updateItem=function(itemObj,index,isLast)
        CommonHelper:SetGameObjectActive("num/1",itemObj,false)
        CommonHelper:SetGameObjectActive("num/2",itemObj,false)
        CommonHelper:SetGameObjectActive("num/3",itemObj,false)
        CommonHelper:SetGameObjectActive("num/"..(index),itemObj,true)
        CommonHelper:SetGameObjectActive("unmatch",itemObj,false)
        CommonHelper:SetGameObjectActive("unjoin",itemObj,false)
        CommonHelper:SetGameObjectActive("matchover",itemObj,false)
        local shellId = RaceJcpManager:Get():GetCarShellByIndex(index,isLast)
        if shellId~=nil and shellId>0 then
            CommonHelper:SetGameObjectActive("matchover",itemObj,true)
            ---@type dictparts_config_cell
            local ShellCfg = CommonHelper:GetTableDataByID(ConfigNames.parts_config, shellId)
            if ShellCfg then
                CommonHelper:SetText("###iconname",itemObj,CommonHelper:GetTempStr_Default(ShellCfg.partname))
                --CommonHelper:GetComponentSetUITexture("iconname",itemObj, ShellCfg.carNameIcon, UIModuleID.RaceJCP)
            end
            local speed = RaceJcpManager:Get():GetRecordInfoByIndex(index,isLast)
            if speed==nil or speed==0 or speed=="0" then
                CommonHelper:SetText("###speed",itemObj,CommonHelper:GetTempStr_Default(TemplateStringID.JCPFail))
            else
                CommonHelper:GetComponentTransferTime("###speed", itemObj, speed)
            end
        else
            CommonHelper:SetGameObjectActive("unmatch",itemObj,true)
        end
    end
    for i = 1, 3 do
        local bestItem= UIUtil.GetChild( "bestItem_"..i,self.GroupTranscript)
        local lastItem= UIUtil.GetChild( "lastItem_"..i,self.GroupTranscript)
        updateItem(bestItem,i)
        updateItem(lastItem,i,true)
    end
end

function RaceJCPView:SetItem(i,itemObj,scroll)

    if  itemObj then
        local index=i+1
        local  param = RaceJcpManager:Get():GetCarDataByPos(index)
        CommonHelper:SetGameObjectActive("num/1",itemObj,false)
        CommonHelper:SetGameObjectActive("num/2",itemObj,false)
        CommonHelper:SetGameObjectActive("num/3",itemObj,false)
        CommonHelper:SetGameObjectActive("num/"..(index),itemObj,true)
        CommonHelper:SetGameObjectActive("selected",itemObj,false)
        CommonHelper:SetGameObjectActive("unjoin",itemObj,false)
        CommonHelper:SetGameObjectActive("unmatch",itemObj,false)
        CommonHelper:SetGameObjectActive("matchover",itemObj,false)


        if param then
            if  param.CarReviewData:GetShellCfg() then
                CommonHelper:GetComponentSetUITexture("iconname",itemObj, param.CarReviewData:GetShellCfg().carNameIcon, UIModuleID.RaceJCP)
            end
            if param.isnextuse  then
                CommonHelper:SetGameObjectActive("selected",itemObj,true)
            elseif param.isuse then
                CommonHelper:SetGameObjectActive("matchover",itemObj,true)
                local speed = RaceJcpManager:Get():GetRecordInfoByIndex(index)
                if speed==nil or speed==0 or speed=="0" then
                    CommonHelper:SetText("###speed",itemObj,CommonHelper:GetTempStr_Default(TemplateStringID.JCPFail))
                else
                    CommonHelper:GetComponentTransferTime("###speed", itemObj, speed)
                end
            else
                CommonHelper:SetGameObjectActive("unmatch",itemObj,true)
            end
            CommonHelper:SetText("###name",itemObj,param.CarReviewData.Name)
        else
            CommonHelper:SetGameObjectActive("unjoin",itemObj,true)
        end
    end
end

function RaceJCPView:GetTimeStr(time)
    local subTime = time - CommonHelper:ConvertDateTimeToInt(CommonHelper:GetNowTime())
    local day = math.modf(subTime / TimeSecond_Day)
    local hour = math.modf((subTime - (day * TimeSecond_Day)) / TimeSecond_Hour)
    local minute = math.modf((subTime - (day * TimeSecond_Day) - (hour * TimeSecond_Hour)) / TimeSecond_Minute)
    local second = subTime - (day * TimeSecond_Day) - (hour * TimeSecond_Hour) - (minute * TimeSecond_Minute)

    local timeStr
    if day >= 1 then
        timeStr = CommonHelper:GetTempStr_Default(TemplateStringID.CommonCountDownTime, day, hour, minute)
    else
        timeStr = CommonHelper:GetTempStr_Default(TemplateStringID.CommonCountDownTimeSecond, hour, minute, second)
    end

    return timeStr
end

function RaceJCPView:CountDownTime()
    if  self.cs_countdown == nil then
        if RaceJcpManager:Get():GetCurState()~=RaceJCPType.RaceOver then
            self.cs_countdown = cs_coroutine.start(function()
                while RaceJcpManager:Get():GetCurState()~=RaceJCPType.RaceOver do
                    CommonHelper:SetText("###CountTxt", self.Page_CarInfo,self:GetTimeStr(self.over_time))
                    CommonHelper:SetText("###CountTxt", self.window_bg_right,self:GetTimeStr(self.time))
                    coroutine.yield(CS.UnityEngine.WaitForSeconds(0.5))
                    if  CommonHelper:ConvertNowTimeDouble() > self.time then
                        local curState = RaceJcpManager:Get():GetCurState()
                        RaceJcpManager:Get().JcpData:CalculateState()
                        if curState ~= RaceJcpManager:Get():GetCurState() then
                            UINotify:Get():SendNotification(UINotifyEvent.RaceJCPView_SetData)
                        end
                    end
                    if RaceJcpManager:Get():GetCurState() == RaceJCPType.ApplyAfter then
                        CommonHelper:SetText("###jointip", self.window_bg_right,CommonHelper:GetTempStr_Default(TemplateStringID.JCPJoinUnStart))
                        CommonHelper:SetText("###jointip1", self.window_bg_right,CommonHelper:GetTempStr_Default(TemplateStringID.JCPJoinCountDown))
                    elseif RaceJcpManager:Get():GetCurState() == RaceJCPType.ApplyIng or RaceJcpManager:Get():GetCurState() == RaceJCPType.ApplySuccess then
                        CommonHelper:SetText("###jointip", self.window_bg_right,CommonHelper:GetTempStr_Default(TemplateStringID.JCPActivityUnStart))
                        CommonHelper:SetText("###jointip1", self.window_bg_right,CommonHelper:GetTempStr_Default(TemplateStringID.JCPActivityCountDown))
                    end
                end
            end)
        end
    end
end

