    self.TrackData = RaceJcpManager:Get():GetTrackData()
    self.SceneId = RaceJcpManager:Get():GetSceneID()
    CommonHelper:GetComponentSetTrackIconByData("trackicon", self.gameObject, self.TrackData, UIModuleID.RaceJCP)
    CommonHelper:SetTrackFeatureByParent("trackfeature", self.gameObject, self.TrackData:GetFeature(), true)
    if self.SceneId ~= -1 then
        ---@type scene_config_cell
        local sceneCfg = CommonHelper:GetTableDataByID(ConfigNames.scene_config, self.SceneId)
        if sceneCfg then
            CommonHelper:GetComponentSetUITexture("chapterpic", self.gameObject, sceneCfg.icon, UIModuleID.RaceJCP)
        end
    end
    CommonHelper:HButtonSetCallback("BtnReview", self.gameObject, function(data)
        if self.TrackData:GetIsField() then
            CommonTipsHelper:Get():ShowCenterTips(CommonHelper:GetTempStr_Default(TemplateStringID.TrackFieldNoLook))
        else
            CommonHelper:LoadReviewTrack(nil, self.TrackData)
        end
    end)
end

function RaceJCPView:OnClose()
    if  self.cs_countdown ~=nil then
        cs_coroutine.stop(self.cs_countdown)
        self.cs_countdown = nil
    end
    CarBuilderTextureManager:Get():Clear()
end

function RaceJCPView:OnOpenAnimEnd()
    if RaceJcpManager:Get():IsJoin() then
        for i = 1, #RaceJcpManager:Get().JcpData.buildParams do
            self.curCarIndex=RaceJcpManager:Get().JcpData.buildParams[i].idx
            if RaceJcpManager:Get().JcpData.buildParams[i].isnextuse then
                break
            end
        end
        --self:BuildApplyCars()
    end
end